import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

const minio = new S3Client({
  region: 'us-east-1',
  endpoint: '{{minio_endpoint}}',
  forcePathStyle: true,
  credentials: {
    accessKeyId: '{{access_key}}',
    secretAccessKey: '{{secret_key}}',
  },
});

export async function minioPut(key: string, body: Buffer, contentType: string) {
  await minio.send(new PutObjectCommand({
    Bucket: '{{bucket_name}}',
    Key: key,
    Body: body,
    ContentType: contentType,
  }));
}

export async function minioPresignedPut(key: string) {
  const cmd = new PutObjectCommand({ Bucket: '{{bucket_name}}', Key: key });
  return await getSignedUrl(minio, cmd, { expiresIn: 900 });
}
